$ErrorActionPreference='Stop'
$review='C:\Users\gb\.codex\tmp\pvground_extremal_span_evidence_20261009\runner_v1\source_review'
$baseline=@(Get-Content -LiteralPath "$review\R2_R1_PRESERVATION_BASELINE.json" -Raw -Encoding utf8 | ConvertFrom-Json)
foreach($entry in $baseline) {if((Get-FileHash -LiteralPath $entry.path -Algorithm SHA256).Hash.ToLower() -ne $entry.sha256) {throw "R1 artifact changed: $($entry.path)"}}
$manifest=@(Get-Content -LiteralPath "$review\INPUT_MANIFEST_R2.json" -Raw -Encoding utf8 | ConvertFrom-Json)
foreach($entry in $manifest) {if((Get-FileHash -LiteralPath (Join-Path $review $entry.snapshot) -Algorithm SHA256).Hash.ToLower() -ne $entry.sha256) {throw "R2 snapshot changed: $($entry.snapshot)"}}
$rawHash=(Get-FileHash -LiteralPath "$review\RAW_RESPONSE_R2.md" -Algorithm SHA256).Hash.ToLower()
if($rawHash -ne (Get-FileHash -LiteralPath "$review\SOURCE_REVIEW_R2.md" -Algorithm SHA256).Hash.ToLower()) {throw 'R2 raw report mismatch'}
$result=[pscustomobject]@{time_utc=[DateTime]::UtcNow.ToString('o');scope='STATIC_ONLY';R1_artifacts_preserved=$baseline.Count;R2_snapshots_exact=$manifest.Count;raw_report_exact=$true;raw_report_sha256=$rawHash;reviewed_loop_sha256='c6b8328aee7ae7369d5636b11ce31eb06b53267af1358e4667cc3e8e88df0d5d';live_source_successor_review_separate=$true}
$result | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath "$review\R2_FINAL_VERIFICATION.json" -Encoding utf8
$result | ConvertTo-Json -Depth 5
